import type { Config } from './createConfig';
import { PUBLIC_SELECTED_CONFIG } from '$env/static/public';
import { defaultConfig } from './items/default';
import { stagingConfig } from './items/staging';

export const configs: Record<string, Config> = {
	default: defaultConfig,
	staging: stagingConfig
};

export const getConfig = () => {
	return configs[PUBLIC_SELECTED_CONFIG || 'default'];
};

export const config = getConfig();

import type { PayloadTypes } from '$lib/payload-types';
import { defaultConfig } from './items/default';

export type Config = typeof defaultConfig & {
	localization: {
		urls: Record<PayloadTypes.Config['locale'], string[]>;
	};
};

export const createConfig = (config: Partial<Config> & Record<string, unknown>): Config => {
	return { ...defaultConfig, ...config };
};

export const defaultConfig = {
  blockGoogleIndexing: true,
  urls: {
    default: {
      nl: 'http://localhost:4000',
      de: 'http://localhost:4000',
    },
    internal: 'http://localhost:4000',
    cdn: undefined as string | undefined
  },
  sentry: {
    enabled: false,
    environment: 'development',
    dsn: undefined as string | undefined,
  },
  localization: {
    urls: {
      nl: ['http://app-nl.localhost:3000'],
      de: ['http://app-de.localhost:3000']
    }
  },
  mapbox: {
    accessToken: 'YOUR_MAPBOX_PUBLIC_TOKEN',
  },
  cache: {
    enabled: true,
    ttl: 15 * 1000
  }
};

import type { Config } from '../createConfig';
import { defaultConfig } from './default';

export const stagingConfig: Config = {
  ...defaultConfig,
  blockGoogleIndexing: true,
  urls: {
    default: {
      nl: 'https://preview.example-nl.com',
      de: 'https://preview.example-de.com'
    },
    internal: 'http://backend:4000',
    cdn: 'https://cdn.example.com'
  },
  sentry: {
    ...defaultConfig.sentry,
    enabled: true,
    environment: 'staging'
  },
  localization: {
    urls: {
      nl: ['https://preview.example-nl.com'],
      de: ['https://preview.example-de.com']
    }
  },
  cache: {
    ...defaultConfig.cache,
    enabled: true
  }
};

import type { PayloadTypes } from '$lib/payload-types';
import { config } from '../../config/config';
import { page } from '$app/state';

export const getLocalizationByHostname = (url: URL): PayloadTypes.Config['locale'] => {
	const locale = Object.keys(config.localization.urls).find((locale) =>
		config.localization.urls[locale as PayloadTypes.Config['locale']].some((hostname) =>
			url.href.startsWith(hostname)
		)
	) as PayloadTypes.Config['locale'] | undefined;
	return locale || 'nl';
};

export const getLocalization = () => {
	return getLocalizationByHostname(page.url);
};

import { PayloadSDK } from '@payloadcms/sdk';

export function createPayloadClient({ fetchFn, baseUrl, token }: {
  fetchFn?: typeof fetch;
  baseUrl?: string;
  token?: string;
}) {
  const client = new PayloadSDK({
    baseURL: baseUrl ? `${baseUrl}/api` : undefined,
    fetch: fetchFn || fetch,
  });

  return client;
}

import { PayloadSDK } from '@payloadcms/sdk';
import { config } from '../config/config';
import { getLocalizationByHostname } from '$lib/localization/getLocalizationByUrl';
import { browser } from '$app/environment';

type GetSdkParams = {
	fetchFn: typeof fetch;
	parentUrl: URL;
	credentials?: RequestCredentials;
};

const addLocaleToUrl = (incoming: string | URL | Request, parentUrl: URL): URL | Request => {
	const locale = getLocalizationByHostname(parentUrl);
	if (incoming instanceof URL || typeof incoming === 'string') {
		const url = new URL(incoming);
		url.searchParams.set('locale', locale);
		return url;
	}

	const url = new URL(incoming.url);
	url.searchParams.set('locale', locale);

	return new Request(url.toString(), incoming);
};

export const payloadSdk = ({ fetchFn, parentUrl, credentials = 'include' }: GetSdkParams) => {
	const locale = getLocalizationByHostname(parentUrl);
	const defaultUrl = browser ? config.urls.default[locale] : config.urls.internal;

	return new PayloadSDK({
		baseURL: `${defaultUrl}/api`,
		fetch: async (url, init?) => {
			url = addLocaleToUrl(url, parentUrl);
			const headers = new Headers(init?.headers);
			headers.set('Force-Locale', '1');
			headers.set('Frontend', '1');
			const response = await fetchFn(url, {
				...init,
				credentials,
				headers
			});

			return response;
		}
	});
};

